from lib import Q
C='nail-structure'
Q(C,'basic',"손톱을 만들어 내는 곳으로, 다치면 손톱이 제대로 자라지 못하는 부분은?","매트릭스(조모)",[("네일 베드(조상)","손톱 아래에서 손톱을 받치는 피부입니다."),("프리에지(자유연)","손끝 밖으로 자라 나온 손톱 끝입니다."),("하이포니키움(하조피)","프리에지 아래의 피부입니다.")],"손톱 생성 = 매트릭스(조모)","**매트릭스(조모)**는 손톱 뿌리 아래에서 새 손톱 세포를 만들어 내는 곳입니다. 혈관과 신경이 있어 다치면 손톱이 비뚤게 자라거나 자라지 않을 수 있습니다.",5,["자연 네일 구조"])
Q(C,'intermediate',"손톱 뿌리 쪽에 보이는 반달 모양의 하얀 부분은?","루눌라(반월)",[("큐티클(조소피)","손톱 뿌리 둘레를 덮는 각질 피부입니다."),("프리에지(자유연)","손톱 끝부분입니다."),("네일 그루브(조구)","손톱 양옆의 홈입니다.")],"반달 모양 흰 부분 = 루눌라","**루눌라(반월)**는 손톱 뿌리 쪽의 반달 모양 하얀 부분으로 매트릭스의 일부가 비쳐 보이는 곳입니다. 아직 완전히 각질화되지 않아 하얗게 보입니다.",5,["자연 네일 구조"])
Q(C,'basic',"손톱(네일 바디) 아래에 있으며 혈관과 신경이 많아 손톱이 분홍색으로 보이게 하는 부분은?","네일 베드(조상)",[("매트릭스(조모)","손톱을 만들어 내는 곳으로 손톱 뿌리 아래에 있습니다."),("프리에지(자유연)","손끝 밖으로 자라 나온 손톱 끝입니다."),("큐티클(조소피)","손톱 뿌리 둘레의 각질 피부입니다.")],"손톱 아래 분홍 부분 = 네일 베드","**네일 베드(조상)**는 네일 바디를 받치는 피부로 혈관과 신경이 많습니다. 그래서 건강한 손톱은 분홍색으로 보입니다.",5,["자연 네일 구조"])
Q(C,'intermediate',"프리에지 바로 아래에 있는 피부로, 세균이 손톱 밑으로 들어오는 것을 막는 부분은?","하이포니키움(하조피)",[("에포니키움(상조피)","손톱 뿌리 쪽을 덮는 피부입니다."),("루눌라(반월)","손톱 뿌리 쪽의 반달 모양 부분입니다."),("매트릭스(조모)","손톱을 만들어 내는 곳입니다.")],"프리에지 아래 피부 = 하이포니키움","**하이포니키움(하조피)**은 프리에지 아래에 있는 피부로 세균이 손톱 밑으로 들어오는 것을 막습니다. 파일이나 도구로 세게 긁지 않습니다.",4,["자연 네일 구조"])
Q(C,'intermediate',"손톱 뿌리(네일 루트) 쪽 위를 덮고 있는 피부로, 매트릭스를 보호하는 부분은?","에포니키움(상조피)",[("하이포니키움(하조피)","프리에지 아래의 피부입니다."),("네일 베드(조상)","손톱 아래를 받치는 피부입니다."),("프리에지(자유연)","손톱 끝부분입니다.")],"손톱 뿌리 위 피부 = 에포니키움","**에포니키움(상조피)**은 손톱 뿌리 위를 덮는 피부로 매트릭스를 세균과 이물질로부터 보호합니다. 큐티클을 정리할 때 에포니키움을 잘라 상처 내지 않도록 주의합니다.",4,["자연 네일 구조"])
Q(C,'basic',"손톱을 이루는 주된 단백질은?","케라틴",[("콜라겐","진피를 이루는 단백질입니다."),("엘라스틴","진피의 탄력섬유 단백질입니다."),("헤모글로빈","적혈구 속에서 산소를 운반하는 단백질입니다.")],"손톱 = 케라틴 단백질","손톱은 단단한 **케라틴** 단백질로 이루어져 있습니다. 모발과 표피의 각질층도 케라틴으로 되어 있습니다.",5,["자연 네일 특징"])
Q(C,'basic',"손톱과 발톱이 자라는 속도에 대한 설명으로 옳은 것은?","손톱이 발톱보다 빨리 자란다",[("발톱이 손톱보다 빨리 자란다","반대입니다. 발톱이 더 느리게 자랍니다."),("손톱과 발톱은 자라는 속도가 같다","손톱이 더 빨리 자랍니다."),("손톱은 어른이 되면 자라지 않는다","손톱은 평생 계속 자랍니다.")],"성장 속도: 손톱 > 발톱","손톱은 평생 계속 자라며 **발톱보다 빨리** 자랍니다. 그래서 손발톱 관리 주기도 손톱이 더 짧습니다.",4,["자연 네일 특징"])
Q(C,'intermediate',"건강한 손톱이 머금고 있는 수분의 양으로 알맞은 것은?","12~18% 정도",[("1~2% 정도","너무 적습니다. 이 정도면 손톱이 매우 건조하고 잘 부서집니다."),("40~50% 정도","너무 많습니다."),("70~80% 정도","손톱은 그만큼 수분이 많지 않습니다.")],"건강한 손톱 수분 = 12~18%","건강한 손톱은 수분을 **12~18% 정도** 머금고 있어 단단하면서도 적당히 유연합니다. 수분이 부족하면 갈라지고 부서지기 쉽습니다.",4,["자연 네일 특징"])
Q(C,'basic',"건강한 손톱의 조건으로 옳지 않은 것은?","표면에 깊은 세로 홈이 패어 있고 잘 부서진다",[("연한 분홍색을 띤다","건강한 손톱의 조건입니다."),("표면이 매끄럽고 윤기가 있다","건강한 손톱의 조건입니다."),("네일 베드에 단단히 붙어 있다","건강한 손톱의 조건입니다.")],"건강한 손톱 = 분홍색·매끈·단단히 붙음","건강한 손톱은 연한 분홍색이고 표면이 매끄러우며 네일 베드에 단단히 붙어 있고 적당한 탄력이 있습니다. 깊은 홈이 있고 잘 부서지는 것은 건강하지 않은 상태입니다.",4,["자연 네일 특징"],lock=True)
Q(C,'basic',"네일 베드에서 떨어져 손끝 밖으로 자라 나온 손톱 끝부분은?","프리에지(자유연)",[("네일 루트(조근)","피부 속에 묻힌 손톱 뿌리입니다."),("루눌라(반월)","손톱 뿌리 쪽의 반달 모양 부분입니다."),("큐티클(조소피)","손톱 뿌리 둘레의 각질 피부입니다.")],"손톱 끝 = 프리에지","**프리에지(자유연)**는 네일 베드에서 떨어져 앞으로 자라 나온 손톱 끝입니다. 파일로 모양을 만드는 부분입니다.",5,["자연 네일 구조"])
Q(C,'advanced',"손톱 케라틴에 많이 들어 있어 손톱을 단단하게 하는, 황(S)을 가진 아미노산은?","시스테인",[("글리신","황을 가지지 않은 가장 단순한 아미노산입니다."),("트립토판","황을 가지지 않은 아미노산입니다."),("알라닌","황을 가지지 않은 아미노산입니다.")],"손톱 케라틴의 황 함유 아미노산 = 시스테인","손톱 케라틴에는 황을 가진 아미노산인 **시스테인**이 많습니다. 시스테인끼리 이어지는 결합이 손톱을 단단하게 합니다.",3,["자연 네일 특징"])

C='nail-basic-care'
Q(C,'basic',"자연 네일을 파일링할 때 바른 방법은?","한 방향으로 파일링한다",[("앞뒤로 세게 왕복하며 파일링한다","왕복하면 손톱 끝이 갈라지고 층이 벗겨지기 쉽습니다."),("물에 오래 불린 직후 세게 파일링한다","불린 손톱은 약해 쉽게 상합니다."),("거친 80그릿 파일로 빨리 갈아 낸다","거친 파일은 자연 네일을 상하게 합니다.")],"자연 네일 파일링 = 한 방향","자연 네일은 **한 방향으로** 부드럽게 파일링해야 손톱 끝이 갈라지거나 층이 벗겨지지 않습니다.",5,["파일링"])
Q(C,'basic',"네일 파일의 그릿(grit) 숫자에 대한 설명으로 옳은 것은?","숫자가 클수록 입자가 곱다",[("숫자가 클수록 입자가 거칠다","반대입니다. 숫자가 작을수록 거칩니다."),("숫자는 파일의 길이를 뜻한다","그릿은 입자의 거칠기를 나타냅니다."),("숫자는 파일의 두께를 뜻한다","그릿은 입자의 거칠기를 나타냅니다.")],"그릿 숫자 클수록 곱다","파일의 **그릿** 숫자는 연마 입자의 거칠기를 나타냅니다. **숫자가 클수록 곱고**, 작을수록 거칩니다. 자연 네일에는 고운 파일, 인조 네일의 두께를 줄일 때는 거친 파일을 씁니다.",5,["파일링"])
Q(C,'intermediate',"자연 네일의 프리에지 모양을 다듬을 때 쓰기에 가장 알맞은 파일은?","180그릿 정도의 고운 파일",[("100그릿 파일","인조 네일을 다듬는 거친 파일로 자연 네일에는 거칩니다."),("80그릿 파일","매우 거칠어 자연 네일을 상하게 합니다."),("60그릿 파일","가장 거친 편으로 자연 네일에 쓰지 않습니다.")],"자연 네일 = 180그릿 이상 고운 파일","자연 네일은 약하므로 **180그릿 이상**의 고운 파일을 씁니다. 100그릿 이하의 거친 파일은 인조 네일의 길이와 두께를 다듬을 때 씁니다.",4,["파일링"])
Q(C,'intermediate',"메탈 푸셔로 큐티클을 밀어 올릴 때의 각도로 알맞은 것은?","약 45°",[("약 90°","도구를 세우면 손톱 표면이 긁히고 상합니다."),("약 10°","너무 눕히면 큐티클이 잘 밀리지 않습니다."),("각도와 상관없이 세게 누른다","세게 누르면 매트릭스를 다칠 수 있습니다.")],"메탈 푸셔 = 약 45°, 부드럽게","메탈 푸셔는 손톱 표면에 대해 **약 45°**로 두고 큐티클을 부드럽게 밀어 올립니다. 세게 누르면 손톱과 매트릭스가 상할 수 있습니다.",4,["큐티클 정리"])
Q(C,'basic',"큐티클 니퍼로 큐티클을 정리하는 방법으로 가장 알맞은 것은?","밀어 올려 들뜬 큐티클만 한 줄로 이어지게 조금씩 잘라 낸다",[("살아 있는 피부까지 깊게 잘라 낸다","깊게 자르면 피가 나고 감염될 수 있습니다."),("큐티클을 손으로 잡아 뜯는다","뜯으면 상처가 생깁니다."),("푸셔로 밀지 않고 바로 크게 잘라 낸다","먼저 불리고 밀어 올린 뒤 들뜬 부분만 정리합니다.")],"니퍼 = 들뜬 큐티클만 조금씩","큐티클은 불리고 푸셔로 밀어 올린 뒤 **들뜬 부분만** 니퍼로 조금씩, 한 줄로 이어지게 잘라 냅니다. 살아 있는 피부를 깊게 자르지 않습니다.",5,["큐티클 정리"])
Q(C,'basic',"매니큐어에서 핑거볼에 손을 담그는 주된 목적은?","미온수로 큐티클을 불려 부드럽게 한다",[("손톱 색을 하얗게 만든다","미온수는 손톱 색을 바꾸지 않습니다."),("손톱을 빨리 자라게 한다","손톱 성장과 관계없습니다."),("폴리시를 빨리 마르게 한다","폴리시를 바르기 전 단계입니다.")],"핑거볼 = 큐티클 불리기","핑거볼에 **미온수**를 담아 손끝을 잠시 담그면 큐티클이 부드러워져 밀어 올리고 정리하기 쉬워집니다.",4,["매니큐어 순서"])
Q(C,'intermediate',"일반 네일 폴리시를 제거하는 방법으로 가장 알맞은 것은?","리무버를 적신 솜을 손톱 위에 잠시 올려 두었다가 큐티클 쪽에서 프리에지 쪽으로 닦아 낸다",[("마른 솜으로 세게 문질러 닦는다","리무버 없이 문지르면 잘 지워지지 않고 손톱이 상합니다."),("메탈 푸셔로 긁어낸다","긁으면 손톱 표면이 상합니다."),("거친 파일로 갈아 낸다","일반 폴리시는 리무버로 녹여 지웁니다.")],"일반 폴리시 = 리무버 솜 잠시 올렸다가 닦기","일반 폴리시는 **리무버를 적신 솜**을 잠시 올려 폴리시를 녹인 뒤 큐티클 쪽에서 프리에지 쪽으로 닦아 냅니다. 큐티클 주변의 잔여물은 오렌지우드스틱에 솜을 말아 정리합니다.",4,["화장물 제거"])
Q(C,'intermediate',"젤 네일 폴리시를 제거하는 방법으로 가장 알맞은 것은?","표면을 파일로 가볍게 갈아 낸 뒤 리무버 적신 솜을 올리고 호일로 감싸 불린다",[("리무버 솜으로 한 번 닦으면 바로 지워진다","젤은 단단히 굳어 있어 한 번 닦아서는 지워지지 않습니다."),("손톱 위의 젤을 손으로 뜯어낸다","뜯으면 자연 네일 층이 함께 떨어집니다."),("램프에 다시 비춰 녹인다","램프는 젤을 굳히는 장비입니다.")],"젤 제거 = 표면 파일링 → 리무버 + 호일 → 밀어내기","젤 폴리시는 굳으면 단단하므로 먼저 **톱 젤 표면을 파일로 갈아** 리무버가 스며들게 합니다. 그다음 리무버 적신 솜을 올리고 **호일로 감싸 불린** 뒤 푸셔로 부드럽게 밀어냅니다.",5,["화장물 제거"])
Q(C,'advanced',"아크릴 인조 네일을 제거하는 방법으로 가장 알맞은 것은?","길이와 두께를 줄인 뒤 아세톤에 불려 녹인다",[("니퍼로 자연 네일에서 떼어 낸다","억지로 떼면 자연 네일까지 떨어져 상합니다."),("논아세톤 리무버로 한 번 닦는다","논아세톤 리무버로는 아크릴이 잘 녹지 않습니다."),("뜨거운 물에 담가 떼어 낸다","뜨거운 물로 아크릴을 녹이지 않습니다.")],"아크릴 제거 = 길이·두께 줄이고 아세톤에 불리기","아크릴 네일은 먼저 니퍼·파일로 **길이와 두께를 줄이고**, **아세톤**에 불려 녹인 뒤 푸셔로 조심스럽게 밀어냅니다. 억지로 떼어 내면 자연 네일이 상합니다.",4,["화장물 제거"])
Q(C,'basic',"큐티클 주변이 건조할 때 보습을 위해 바르는 제품은?","큐티클 오일",[("아세톤","건조하게 만드는 용제입니다."),("프라이머","인조 네일의 접착을 돕는 산성 제품입니다."),("톱 코트","컬러를 보호하는 마지막 코팅입니다.")],"큐티클 보습 = 큐티클 오일","**큐티클 오일**은 큐티클과 손톱 주변 피부에 유분과 보습을 주어 거스러미를 막습니다. 시술 마무리 때 바르고 문질러 흡수시킵니다.",4,["보습"])
Q(C,'basic',"손끝을 많이 쓰는 사람과 발톱에 알맞으며, 가장 튼튼한 프리에지 모양은?","스퀘어",[("포인트","끝이 뾰족해 가장 약하고 잘 부러집니다."),("오벌","여성스럽지만 스퀘어보다 약합니다."),("라운드","무난하지만 모서리를 둥글게 깎아 스퀘어보다 약합니다.")],"가장 튼튼한 모양 = 스퀘어(발톱에도 알맞음)","**스퀘어**는 프리에지를 일자로 하고 모서리를 직각으로 남긴 모양으로 가장 튼튼합니다. 손끝을 많이 쓰는 사람과 발톱에 알맞습니다. 끝이 뾰족한 **포인트**가 가장 약합니다.",4,["프리에지 모양"])
Q(C,'basic',"그림과 같은 프리에지 모양의 이름은?","스퀘어",[("라운드","끝이 반원처럼 둥근 모양입니다."),("포인트","끝이 뾰족한 모양입니다."),("오벌","끝이 달걀처럼 둥글고 길쭉한 모양입니다.")],"일자 끝 + 직각 모서리 = 스퀘어","그림의 손톱은 끝이 **일자**이고 양쪽 모서리가 **직각**입니다. 이 모양을 **스퀘어**라 합니다.",3,["프리에지 모양","그림"],img=("nail-shape-q1.svg","손가락 끝에 손톱 하나가 그려져 있다. 손톱의 양옆은 곧게 올라가고, 손끝 밖으로 나온 프리에지는 가로로 곧은 선이며 양쪽 모서리가 각진 모양이다."))
Q(C,'intermediate',"그림과 같은 프리에지 모양의 이름은?","오벌",[("스퀘어 오프","끝이 일자이고 모서리만 둥근 모양입니다."),("포인트","끝이 뾰족하게 모이는 모양입니다."),("스퀘어","끝이 일자이고 모서리가 직각인 모양입니다.")],"달걀처럼 둥글고 길쭉함 = 오벌","그림의 손톱은 양옆이 끝으로 갈수록 부드럽게 좁아지고, 끝이 뾰족하지 않고 **달걀처럼 둥근** 모양입니다. 이 모양을 **오벌**이라 합니다.",3,["프리에지 모양","그림"],img=("nail-shape-q2.svg","손가락 끝에 손톱 하나가 그려져 있다. 프리에지 쪽으로 가면서 양옆이 부드럽게 좁아지고, 끝은 뾰족하지 않게 둥글게 이어지는 길쭉한 모양이다."))
Q(C,'intermediate',"그림과 같은 프리에지 모양에 대한 설명으로 옳은 것은?","끝이 뾰족한 포인트로, 약해서 부러지기 쉽다",[("끝이 일자인 스퀘어로, 가장 튼튼하다","그림은 끝이 일자가 아니라 뾰족합니다."),("끝이 둥근 라운드로, 가장 무난하다","그림은 끝이 둥글지 않고 뾰족합니다."),("모서리만 둥근 스퀘어 오프로, 튼튼하다","그림은 끝이 한 점으로 모입니다.")],"뾰족한 끝 = 포인트(가장 약함)","그림의 손톱은 양옆이 곧게 좁아져 끝이 **한 점으로 뾰족하게** 모입니다. 이 모양은 **포인트**이며, 끝이 가늘어 힘을 받으면 부러지기 쉽습니다.",3,["프리에지 모양","그림"],img=("nail-shape-q3.svg","손가락 끝에 손톱 하나가 그려져 있다. 프리에지 쪽으로 가면서 양옆이 비스듬히 좁아져 끝이 한 점으로 모이는 모양이다."))
